        self._product = None
        self._data = {}
        self._dtype = None
        self._shape = None
        self.dimensions = {}
        self._variables = None
        self.attributes = {}

        self._fill = fillmissing
        self._copy = copy
        if self.attrs["producttype"] == "ascii":
            self._product = self.filename[0:2].upper()
        self._ancillary = self._get_ancillary(requested=ancillary)

